picture.source:
// A library picture set on the page: fitted by its visible content and resting on the
// bottom of the module, optionally grounded by a soft shadow, with its caption directly
// under the picture rather than under the module.
const d = api.data,
  t = api.theme;
const W = api.width,
  H = api.height;
const info = api.materials[d.material];
if (!info) throw Error(`素材 ${d.material} 不在作品中`);
const size = Number(d.captionSize ?? 15);
const caption = d.caption ? String(d.caption) : "";
const below = caption ? size * 1.8 : 0;
const shade = d.shadow ? Math.max(6, H * 0.05) : 0;
const room = H - below - shade * 0.6;
const k = (d.fit === "cover" ? Math.max : Math.min)(
  W / info.width,
  room / info.height,
);
const pw = Math.min(W, info.width * k),
  ph = Math.min(room, info.height * k);
const top = room - ph;
const root = api.html(
  `<div style="position:relative;width:${W}px;height:${H}px"></div>`,
).firstElementChild;
if (shade) {
  const s = document.createElement("div");
  s.style.cssText = `position:absolute;left:${(W - pw * 0.8) / 2}px;width:${pw * 0.8}px;top:${room - shade * 0.55}px;height:${shade}px;border-radius:50%;background:radial-gradient(closest-side,rgba(0,0,0,.2),rgba(0,0,0,.07) 60%,transparent)`;
  root.append(s);
}
const picture = api.material(d.material, {
  width: pw,
  height: ph,
  fit: d.fit ?? "contain",
  ...(d.color ? { color: d.color } : {}),
});
picture.style.position = "absolute";
picture.style.left = (W - pw) / 2 + "px";
picture.style.top = top + "px";
root.append(picture);
if (caption) {
  const c = document.createElement("div");
  c.textContent = caption;
  c.style.cssText = `position:absolute;left:-20%;right:-20%;top:${room + shade * 0.4 + size * 0.3}px;text-align:center;font-size:${size}px;line-height:1.3;color:${d.color || t.ink || "#222"};white-space:nowrap`;
  root.append(c);
}
return root;

label.source:
// A short label in the work's type with a paper-coloured halo, so it stays legible over
// pictures and lines. Lines break at "\n"; an optional note sits underneath, smaller.
const d = api.data,
  t = api.theme;
const W = api.width,
  H = api.height;
const size = Number(d.size ?? 16);
const align = d.align ?? "center";
const x = align === "start" ? 0 : align === "end" ? W : W / 2;
const anchor = align === "center" ? "middle" : align;
const esc = (s) =>
  String(s).replace(
    /[&<>"]/g,
    (ch) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" })[ch],
  );
const lines = String(d.text ?? "").split("\n");
const note = d.note ? String(d.note).split("\n") : [];
const noteSize = size * 0.78;
const total = lines.length * size * 1.25 + note.length * noteSize * 1.3;
let y = (H - total) / 2 + size * 0.95;
const halo =
  d.halo === false
    ? ""
    : `paint-order="stroke" stroke="${t.paper || "#fff"}" stroke-width="${Math.max(3, size / 4)}" stroke-linejoin="round"`;
const rows = [];
for (const line of lines) {
  rows.push(
    `<text x="${x}" y="${y}" text-anchor="${anchor}" font-size="${size}" font-weight="${d.weight ?? 500}" fill="${d.color || t.ink || "#222"}" ${halo}>${esc(line)}</text>`,
  );
  y += size * 1.25;
}
for (const line of note) {
  rows.push(
    `<text x="${x}" y="${y}" text-anchor="${anchor}" font-size="${noteSize}" fill="${d.noteColor || t.muted || "#777"}" ${halo}>${esc(line)}</text>`,
  );
  y += noteSize * 1.3;
}
return api.svg(
  `<svg viewBox="0 0 ${W} ${H}" width="${W}" height="${H}" style="overflow:visible" font-family="${esc(t.font || "system-ui")}">${rows.join("")}</svg>`,
);

waves.source:
// Rows of gentle waves for water: a sea, a river, a sound or light wave. They roll slowly
// unless `still` is set.
const d = api.data,
  t = api.theme;
const W = api.width,
  H = api.height;
const rows = Number(d.rows ?? 3),
  amp = Number(d.amplitude ?? Math.min(8, H / (rows * 3)));
const len = Number(d.wavelength ?? 64);
const color = d.color || t.accent2 || "#4a7fa8";
const w = Number(d.width ?? t.stroke ?? 1.6);
const wave = (y) => {
  let p = `M${-len} ${y}`;
  for (let x = -len; x < W + len; x += len)
    p += `q${len / 4} ${-amp} ${len / 2} 0t${len / 2} 0`;
  return p;
};
let out = `<style>@keyframes roll{to{transform:translateX(${len}px)}}.roll{animation:roll ${Number(d.period ?? 6)}s linear infinite}</style>`;
for (let i = 0; i < rows; i++) {
  const y = ((i + 0.5) / rows) * H;
  out += `<g class="${d.still ? "" : "roll"}" style="animation-duration:${Number(d.period ?? 6) * (1 + i * 0.35)}s"><path d="${wave(y)}" fill="none" stroke="${color}" stroke-width="${w}" stroke-linecap="round" stroke-opacity="${1 - i * (0.5 / rows)}"/></g>`;
}
return api.svg(
  `<svg viewBox="0 0 ${W} ${H}" width="${W}" height="${H}" style="overflow:hidden">${out}</svg>`,
);

night.source:
// 夜空和海：渐变的天，一闪一闪的星星，海平线以下是深色的水
const { width: w, height: h, data: d } = api;
const stars = [];
for (let i = 0; i < d.stars; i++) {
  const x = (i * 97.3) % w, y = ((i * 53.7) % (h * d.horizon * 0.9));
  stars.push(`<circle cx="${x}" cy="${y}" r="${1 + (i % 3) * 0.6}" fill="#fff"/>`);
}
const svg = api.svg(`<svg viewBox="0 0 ${w} ${h}" preserveAspectRatio="none">
  <defs><linearGradient id="sky" x1="0" y1="0" x2="0" y2="1">
    <stop offset="0" stop-color="${d.top}"/><stop offset="1" stop-color="${d.bottom}"/></linearGradient></defs>
  <rect width="${w}" height="${h * d.horizon}" fill="url(#sky)"/>
  <rect y="${h * d.horizon}" width="${w}" height="${h * (1 - d.horizon)}" fill="${d.sea}"/>
  <g class="stars">${stars.join("")}</g></svg>`);
const dots = svg.querySelectorAll(".stars circle");
api.animate((s) => dots.forEach((c, i) => c.setAttribute("opacity", 0.35 + 0.65 * Math.abs(Math.sin(s * 0.8 + i * 1.7)))));
return svg;

beam.source:
// 灯塔的光：从灯室扫出去的一束光，左右慢慢摆
const { width: w, height: h, data: d } = api;
const svg = api.svg(`<svg viewBox="0 0 ${w} ${h}" style="overflow:visible">
  <defs><radialGradient id="glow" cx="1" cy="0.5" r="1">
    <stop offset="0" stop-color="#fff3c4" stop-opacity=".85"/><stop offset="1" stop-color="#fff3c4" stop-opacity="0"/></radialGradient></defs>
  <g class="beam"><path d="M${w} ${h / 2} L0 ${h / 2 - d.spread} L0 ${h / 2 + d.spread} Z" fill="url(#glow)"/></g>
  <circle cx="${w}" cy="${h / 2}" r="12" fill="#fff6d5" opacity=".9"/></svg>`);
const beam = svg.querySelector(".beam");
api.animate((s) => beam.setAttribute("transform", `rotate(${Math.sin(s * 0.6) * d.swing} ${w} ${h / 2})`));
return svg;
